// HBC+ version marker: registers this tab's HBC+ version when the flow starts, so the
// version check in 'HBC+ health (hbc/health)' (Start tab) sees tabs of different HBC+ versions,
// tabs that are missing, and flows that do not match the packages (sensor.hbc_package_version).
// The entry is removed again when the flow stops (deploy, delete). Bump VERSION on a release.
const VERSION = '1.3.0';
const key = env.get('NR_FLOW_ID') || node.id;
const reg = global.get('hbc_flow_versions') || {};
reg[key] = { tab: env.get('NR_FLOW_NAME') || '?', version: VERSION, since: Date.now() };
global.set('hbc_flow_versions', reg);
node.status({ fill: 'grey', shape: 'dot', text: `HBC+ ${VERSION}` });

finalize:
const key = env.get('NR_FLOW_ID') || node.id;
const reg = global.get('hbc_flow_versions') || {};
delete reg[key];
global.set('hbc_flow_versions', reg);

